// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type BranchingRevenueProps = Record<string, any>;

const BranchingRevenue: React.FC<BranchingRevenueProps> = ({
  backgroundColor = "#232F3E",
  transparentBackground = false,
  durationInSeconds = 10,
  titleText = "Calendar Year Progress",
  targetPercentage = 90,
  highlightColor = "#FF9900",
  emptyCardColor = "#131921",
  textColor = "#FFFFFF",
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Header entry animations
  const headerOpacity = interpolate(frame, [0, 20], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const headerY = interpolate(frame, [0, 20], [-40, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Smoothly spring the percentage up from 0 to targetPercentage
  // Starts after the cards have popped in (frame 45)
  const progressSpring = spring({
    fps,
    frame: frame - 45,
    config: { damping: 25, stiffness: 70, mass: 1 },
  });
  
  const currentPercent = progressSpring * targetPercentage;

  const months = [
    "JAN", "FEB", "MAR", "APR", "MAY", "JUN", 
    "JUL", "AUG", "SEP", "OCT", "NOV", "DEC"
  ];

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center' }}>
      
      {/* Header Section */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          opacity: headerOpacity,
          transform: `translateY(${headerY}px)`,
          marginBottom: 80,
          transition: "none",
        }}
      >
        <div style={{ fontSize: 64, fontWeight: 700, color: textColor, letterSpacing: "-0.02em", marginBottom: 16 }}>
          {titleText}
        </div>
        <div style={{ fontSize: 180, fontWeight: 900, color: highlightColor, fontVariantNumeric: "tabular-nums", lineHeight: 1 }}>
          {currentPercent.toFixed(0)}%
        </div>
      </div>

      {/* Calendar Grid Section */}
      <div style={{ display: "flex", flexDirection: "row", gap: 24 }}>
        {months.map((m, i) => {
          // Entry animation for each month card (staggered)
          const entryScale = spring({
            fps,
            frame: frame - (10 + i * 3),
            config: { damping: 14, stiffness: 120 },
          });

          // Calculate how much of THIS specific card should be filled
          // 12 cards total, so each card represents (100 / 12) = 8.333% of the year
          const cardStartPercent = i * (100 / 12);
          const cardEndPercent = (i + 1) * (100 / 12);
          
          const fillRatioRaw = (currentPercent - cardStartPercent) / (cardEndPercent - cardStartPercent);
          const fillRatio = Math.max(0, Math.min(1, fillRatioRaw));

          return (
            <div 
              key={m} 
              style={{ 
                display: "flex", 
                flexDirection: "column", 
                alignItems: "center", 
                transform: `scale(${entryScale})`,
                transition: "none",
              }}
            >
              {/* Card Background & Fill */}
              <div 
                style={{
                  width: 100, 
                  height: 240, 
                  backgroundColor: emptyCardColor,
                  borderRadius: 12, 
                  overflow: "hidden", 
                  position: "relative",
                  boxShadow: "0 10px 30px rgba(0,0,0,0.3)",
                  transition: "none",
                }}
              >
                <div 
                  style={{
                    position: "absolute", 
                    top: 0, 
                    left: 0, 
                    bottom: 0,
                    width: `${fillRatio * 100}%`,
                    backgroundColor: highlightColor,
                    boxShadow: fillRatio > 0 ? `0 0 20px ${highlightColor}80` : "none",
                    transition: "none",
                  }} 
                />
              </div>

              {/* Month Label */}
              <span 
                style={{ 
                  marginTop: 24, 
                  fontSize: 28, 
                  fontWeight: 600, 
                  color: fillRatio > 0.5 ? highlightColor : textColor,
                  transition: "none",
                }}
              >
                {m}
              </span>
            </div>
          );
        })}
      </div>

    </AbsoluteFill>
  );
};

export default BranchingRevenue;